#include <algorithm>
#include <cstdint>
#include <format>
#include <iostream>
#include <span>
#include <string>
#include <vector>

struct Interval {
  std::int64_t start;
  std::int64_t end;  // closed in this problem: [start, end]
};

[[nodiscard]] std::vector<Interval> merge_intervals(std::span<const Interval> intervals) {
  std::vector<Interval> sorted(intervals.begin(), intervals.end());
  std::ranges::sort(sorted, {}, &Interval::start);
  std::vector<Interval> merged;
  for (const Interval& next : sorted) {
    if (!merged.empty() && next.start <= merged.back().end)
      merged.back().end = std::max(merged.back().end, next.end);  // overlaps the last block: extend it
    else
      merged.push_back(next);  // starts after the last block ends: a new block
  }
  return merged;
}

[[nodiscard]] std::string show(std::span<const Interval> intervals) {
  std::string out;
  for (const Interval& i : intervals) out += std::format("[{},{}] ", i.start, i.end);
  return out.empty() ? "none" : out;
}

int main() {
  const std::vector<std::vector<Interval>> cases{
      {{1, 3}, {2, 6}, {8, 10}, {15, 18}},
      {{1, 4}, {4, 5}},
      {{8, 10}, {1, 10}, {2, 3}},
      {},
  };
  for (const std::vector<Interval>& intervals : cases) std::cout << show(merge_intervals(intervals)) << '\n';
}

