struct Interval {
  std::int64_t start;
  std::int64_t end;
};

// The sweep from the cold check, without its sort.
[[nodiscard]] std::vector<Interval> sweep(std::span<const Interval> intervals) {
  std::vector<Interval> merged;
  for (const Interval& next : intervals) {
    if (!merged.empty() && next.start <= merged.back().end)
      merged.back().end = std::max(merged.back().end, next.end);
    else
      merged.push_back(next);
  }
  return merged;
}

[[nodiscard]] std::string show(std::span<const Interval> intervals) {
  std::string out;
  for (const Interval& i : intervals) out += std::format("[{},{}] ", i.start, i.end);
  return out;
}

int main() {
  std::vector<Interval> windows{{1, 3}, {8, 10}, {2, 6}};
  std::cout << "sweep only:       " << show(sweep(windows)) << '\n';
  std::ranges::sort(windows, {}, &Interval::start);
  std::cout << "sort, then sweep: " << show(sweep(windows)) << '\n';
}

#include <algorithm>
#include <cstdint>
#include <format>
#include <iostream>
#include <span>
#include <string>
#include <vector>

struct Window {
  std::int64_t start;  // minutes since midnight, half-open: [start, end)
  std::int64_t end;
};

// The free parts of `day`; every booking lies inside it. Empty bookings are skipped.
[[nodiscard]] std::vector<Window> free_gaps(std::span<const Window> bookings, Window day) {
  std::vector<Window> sorted(bookings.begin(), bookings.end());
  std::ranges::sort(sorted, {}, &Window::start);
  std::vector<Window> gaps;
  std::int64_t covered_until = day.start;  // [day.start, covered_until) is booked or already reported
  for (const Window& booking : sorted) {
    if (booking.start >= booking.end) continue;  // an empty booking would split a gap in two
    if (booking.start > covered_until) gaps.push_back({.start = covered_until, .end = booking.start});
    covered_until = std::max(covered_until, booking.end);
  }
  if (covered_until < day.end) gaps.push_back({.start = covered_until, .end = day.end});
  return gaps;
}

[[nodiscard]] std::string hhmm(std::int64_t minutes) { return std::format("{:02}:{:02}", minutes / 60, minutes % 60); }

int main() {
  const std::vector<Window> bookings{{600, 660}, {480, 540}, {630, 720}, {540, 570}, {900, 960}, {930, 945}};
  for (const Window& gap : free_gaps(bookings, {.start = 0, .end = 24 * 60}))
    std::cout << std::format("free {} to {}\n", hhmm(gap.start), hhmm(gap.end));
}

#include <algorithm>
#include <cstdint>
#include <format>
#include <iostream>
#include <span>
#include <utility>
#include <vector>

struct Interval {
  std::int64_t start;  // half-open: [start, end)
  std::int64_t end;
};

[[nodiscard]] bool can_attend_all(std::span<const Interval> meetings) {
  std::vector<Interval> sorted(meetings.begin(), meetings.end());
  std::ranges::sort(sorted, {}, &Interval::start);
  const auto overlap = [](const Interval& a, const Interval& b) { return b.start < a.end; };
  return std::ranges::adjacent_find(sorted, overlap) == sorted.end();
}

[[nodiscard]] std::int64_t rooms_needed(std::span<const Interval> meetings) {
  std::vector<std::pair<std::int64_t, int>> events;  // (time, +1 at a start or -1 at an end)
  events.reserve(2 * meetings.size());
  for (const Interval& m : meetings) {
    events.emplace_back(m.start, +1);
    events.emplace_back(m.end, -1);
  }
  std::ranges::sort(events);  // at equal times -1 sorts before +1: a room is freed before it is taken again
  std::int64_t in_use = 0;
  std::int64_t most = 0;
  for (const auto& [time, change] : events) {
    in_use += change;
    most = std::max(most, in_use);
  }
  return most;
}

int main() {
  const std::vector<std::vector<Interval>> cases{
      {{0, 30}, {5, 10}, {15, 20}}, {{7, 10}, {2, 4}}, {{9, 10}, {10, 11}}, {{1, 5}, {2, 6}, {3, 7}, {5, 8}}, {}};
  for (const std::vector<Interval>& meetings : cases)
    std::cout << std::format("attend all: {:<5}  rooms: {}\n", can_attend_all(meetings), rooms_needed(meetings));
}

#include <algorithm>
#include <cstdint>
#include <format>
#include <iostream>
#include <span>
#include <string>
#include <vector>

struct Interval {
  std::int64_t start;  // half-open: [start, end)
  std::int64_t end;
};

[[nodiscard]] std::vector<Interval> insert_window(std::span<const Interval> windows, Interval added) {
  std::vector<Interval> out;
  out.reserve(windows.size() + 1);
  auto it = windows.begin();
  for (; it != windows.end() && it->end < added.start; ++it) out.push_back(*it);  // ends before, not touching
  for (; it != windows.end() && it->start <= added.end; ++it) {                 // overlaps or touches
    added.start = std::min(added.start, it->start);
    added.end = std::max(added.end, it->end);
  }
  out.push_back(added);
  out.insert(out.end(), it, windows.end());
  return out;
}

[[nodiscard]] std::string show(std::span<const Interval> windows) {
  std::string out;
  for (const Interval& w : windows) out += std::format("[{},{}) ", w.start, w.end);
  return out;
}

int main() {
  const std::vector<Interval> two{{1, 3}, {6, 9}};
  const std::vector<Interval> five{{1, 2}, {3, 5}, {6, 7}, {8, 10}, {12, 16}};
  std::cout << show(insert_window(two, {2, 5})) << '\n';
  std::cout << show(insert_window(five, {4, 8})) << '\n';
  std::cout << show(insert_window(two, {3, 6})) << '\n';
  std::cout << show(insert_window({}, {4, 5})) << '\n';
  std::cout << show(insert_window(two, {-2, 0})) << '\n';
  std::cout << show(insert_window(two, {10, 12})) << '\n';
}

#include <algorithm>
#include <cstdint>
#include <format>
#include <iostream>
#include <span>
#include <string>
#include <utility>
#include <vector>

struct Interval {
  std::int64_t start;
  std::int64_t end;
};

[[nodiscard]] std::string show(std::span<const Interval> intervals) {
  std::string out;
  for (const Interval& i : intervals) out += std::format("[{},{}] ", i.start, i.end);
  return out;
}

// The cold check's merge with one change: the end is assigned instead of taking the larger one.
[[nodiscard]] std::vector<Interval> merge_without_max(std::vector<Interval> intervals) {
  std::ranges::sort(intervals, {}, &Interval::start);
  std::vector<Interval> merged;
  for (const Interval& next : intervals) {
    if (!merged.empty() && next.start <= merged.back().end)
      merged.back().end = next.end;
    else
      merged.push_back(next);
  }
  return merged;
}

// Exercise 1's count, which expects half-open intervals.
[[nodiscard]] std::int64_t rooms_needed(std::span<const Interval> meetings) {
  std::vector<std::pair<std::int64_t, int>> events;
  for (const Interval& m : meetings) {
    events.emplace_back(m.start, +1);
    events.emplace_back(m.end, -1);
  }
  std::ranges::sort(events);
  std::int64_t in_use = 0;
  std::int64_t most = 0;
  for (const auto& [time, change] : events) {
    in_use += change;
    most = std::max(most, in_use);
  }
  return most;
}

int main() {
  const std::vector<Interval> nested{{1, 10}, {2, 3}, {4, 5}};
  std::cout << "without std::max: " << show(merge_without_max(nested)) << '\n';

  // Closed shifts in whole minutes: both hold minute 10.
  const std::vector<Interval> closed{{9, 10}, {10, 11}};
  std::vector<Interval> half_open;
  for (const Interval& c : closed) half_open.push_back({.start = c.start, .end = c.end + 1});  // [a, b] is [a, b + 1)
  std::cout << "closed, counted as half-open: " << rooms_needed(closed) << " room\n";
  std::cout << "converted first:              " << rooms_needed(half_open) << " rooms\n";
}
